import { DiagnosticData } from '../types/pathology.js';
import { MODEL_CONFIG } from '../constants/modelConfig.js';
import { SERVER_STRINGS } from '../constants/serverStrings.js';
import { logger } from '../utils/logger.js';

export interface ParsedDiagnosticResult {
  markdownReport: string;
  diagnosticData: DiagnosticData;
}

/**
 * Extracts the Markdown diagnostic report and structured DiagnosticData
 * from the complete raw text generated by the vision-language model.
 * Open-ended to support any plant pathogen category, crop, and disease.
 */
export function parseModelResponse(rawText: string): ParsedDiagnosticResult {
  // Strip any lingering <think>...</think> internal reasoning blocks from final output
  const cleanedText = rawText.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
  const jsonBlockRegex = /```json\s*([\s\S]*?)\s*```/;
  const match = jsonBlockRegex.exec(cleanedText);

  let markdownReport = cleanedText;
  let parsedJson: Partial<DiagnosticData> | null = null;

  if (match && match[1]) {
    try {
      parsedJson = JSON.parse(match[1]);
      // Remove JSON code block from markdown report to avoid raw JSON in chat bubble
      markdownReport = rawText.replace(match[0], '').trim();
    } catch (parseError) {
      logger.warn('Failed to parse JSON code block from model output', { error: parseError });
    }
  }

  // Construct validated DiagnosticData with resilient fallbacks
  const diagnosticData: DiagnosticData = {
    crop:
      parsedJson?.crop ||
      extractFieldFromText(rawText, /Target Crop|Host Crop|Host Plant|Crop:\s*\*?\*?([^\n*]+)/i) ||
      'Crop Specimen (Unspecified)',
    disease:
      parsedJson?.disease ||
      extractFieldFromText(rawText, /Identified Disease|Pathology Assessment|Disease:\s*\*?\*?([^\n*]+)/i) ||
      'Unidentified Foliar Condition',
    pathogenType:
      parsedJson?.pathogenType ||
      extractFieldFromText(rawText, /Pathogen Type|Pathogen Category|Pathogen:\s*\*?\*?([^\n*]+)/i) ||
      MODEL_CONFIG.DEFAULT_PATHOGEN_TYPE,
    confidence:
      parsedJson && typeof parsedJson.confidence === SERVER_STRINGS.TYPEOF_NUMBER
        ? (parsedJson.confidence as number)
        : MODEL_CONFIG.DEFAULT_CONFIDENCE,
    severity:
      parsedJson?.severity ||
      extractFieldFromText(rawText, /Severity Level|Severity Rating|Severity:\s*\*?\*?([^\n*]+)/i) ||
      MODEL_CONFIG.DEFAULT_SEVERITY,
    symptoms:
      Array.isArray(parsedJson?.symptoms) && parsedJson.symptoms.length > 0
        ? parsedJson.symptoms
        : ['Observed foliar lesions and leaf tissue distress'],
    organicTreatment:
      parsedJson?.organicTreatment ||
      'Apply biological bio-fungicide (Trichoderma viride or Bacillus subtilis) as preventive measure.',
    chemicalTreatment:
      parsedJson?.chemicalTreatment ||
      'Consult local agronomic extension officer for registered protective treatments.',
    preventativeAction:
      parsedJson?.preventativeAction ||
      'Ensure proper plant spacing, drip irrigation, and lower canopy hygiene.',
  };

  return {
    markdownReport,
    diagnosticData,
  };
}

function extractFieldFromText(text: string, regex: RegExp): string | null {
  const match = regex.exec(text);
  if (match && match[1]) {
    return match[1].trim();
  }
  return null;
}
